using Microsoft.AspNetCore.Mvc;
namespace EduMark.Api.Middleware;
public sealed class ExceptionHandlingMiddleware(RequestDelegate next, ILogger<ExceptionHandlingMiddleware> logger) { public async Task Invoke(HttpContext context) { try { await next(context); } catch (InvalidOperationException ex) { logger.LogWarning(ex, "Business rule rejected {TraceId}", context.TraceIdentifier); await Write(context, 409, "Business rule conflict", ex.Message); } catch (Exception ex) { logger.LogError(ex, "Unhandled error {TraceId}", context.TraceIdentifier); await Write(context, 500, "Unexpected server error", "An unexpected error occurred."); } } private static Task Write(HttpContext c, int s, string t, string d) { c.Response.StatusCode = s; return c.Response.WriteAsJsonAsync(new ProblemDetails { Status = s, Title = t, Detail = d, Instance = c.Request.Path }); } }
